:root {
  --bg-card: #0d0f1a;
  --bg-header: #13162b;
  --bg-footer: #10121f;
  --accent-neon: #00f0c0;
  --accent-orange: #ff6b2b;
  --accent-purple: #7c4dff;
  --accent-yellow: #ffd740;
  --text-primary: #e8eaf6;
  --text-muted: #7986a8;
  --stat-bg: #1a1e35;
  --finish-1: #ffd740;
  --finish-2: #b0bec5;
  --finish-3: #ff8a65;
  --batt-track: #1e2340;
  --batt-fill: #00f0c0;
  --badge-bg: #7c4dff;
}

.pilot-card {
  width: 480px;
  background: var(--bg-card);
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--accent-purple);
  display: flex;
  flex-direction: column;
}

.card-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 2px solid var(--accent-purple);
}

.league-badge {
  background: var(--badge-bg);
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 800;
  padding: 6px 10px;
  border-radius: 8px;
  letter-spacing: 1px;
  flex-shrink: 0;
}

.header-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.season-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--accent-neon);
  letter-spacing: 2px;
  text-transform: uppercase;
}

.pilot-name {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.pilot-number {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-orange);
  letter-spacing: 1px;
}

.status-chip {
  background: var(--accent-neon);
  color: var(--bg-card);
  font-size: 10px;
  font-weight: 800;
  padding: 4px 8px;
  border-radius: 20px;
  letter-spacing: 1.5px;
  flex-shrink: 0;
}

.card-body {
  display: flex;
  gap: 0;
  flex: 1;
}

.avatar-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px 14px;
  border-right: 1px solid #1e2340;
  min-width: 110px;
}

.avatar {
  width: 64px;
  height: 64px;
  background: var(--stat-bg);
  border-radius: 50%;
  border: 2px solid var(--accent-neon);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  font-size: 30px;
  line-height: 1;
}

.avatar-emoji {
  font-size: 30px;
  line-height: 1;
}

.drone-tag {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.drone-label {
  font-size: 9px;
  color: var(--text-muted);
  font-weight: 600;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.drone-model {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-orange);
}

.class-tag {
  background: var(--accent-purple);
  color: var(--text-primary);
  font-size: 9px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 10px;
  letter-spacing: 0.5px;
}

.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 1px;
  flex: 1;
  background: #1e2340;
}

.stat-cell {
  background: var(--stat-bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 12px 8px;
  gap: 2px;
}

.stat-val {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1;
}

.stat-unit {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.stat-name {
  font-size: 9px;
  font-weight: 700;
  color: var(--accent-neon);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-top: 2px;
}

.top-speed .stat-val { color: var(--accent-orange); }
.best-lap .stat-val { color: var(--accent-neon); }
.wins .stat-val { color: var(--accent-yellow); }
.rank .stat-val { color: var(--accent-purple); }

.card-footer {
  background: var(--bg-footer);
  border-top: 1px solid #1e2340;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 16px;
}

.track-history {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}

.track-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.track-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.track-item {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-primary);
  padding-left: 10px;
  position: relative;
}

.track-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

.finish-1::before { background: var(--finish-1); }
.finish-2::before { background: var(--finish-2); }
.finish-3::before { background: var(--finish-3); }

.battery-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
  min-width: 80px;
}

.batt-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.batt-bar {
  width: 80px;
  height: 8px;
  background: var(--batt-track);
  border-radius: 4px;
  overflow: hidden;
}

.batt-fill {
  width: 78%;
  height: 100%;
  background: var(--batt-fill);
  border-radius: 4px;
}

.batt-pct {
  font-size: 10px;
  font-weight: 700;
  color: var(--accent-neon);
}

.freq-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.freq-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.freq-val {
  font-size: 13px;
  font-weight: 800;
  color: var(--accent-yellow);
  letter-spacing: 0.5px;
}
